B.bEK=s(["Me pongo un sombrero.","T\xf4i \u0111\u1ed9i m\u0169."],t.s)
B.bpx=s(["Pap\xe1 tiene un reloj de pulsera.","B\u1ed1 c\xf3 \u0111\u1ed3ng h\u1ed3 \u0111eo tay."],t.s)
B.buL=s(["La sand\xeda es dulce.","D\u01b0a h\u1ea5u ng\u1ecdt."],t.s)
B.bUR=s(["Bebo leche.","T\xf4i u\u1ed1ng s\u1eefa."],t.s)
B.bfN=s(["El pan huele rico.","B\xe1nh m\xec th\u01a1m qu\xe1."],t.s)
B.b3_=s(["Como un huevo.","T\xf4i \u0103n tr\u1ee9ng."],t.s)
B.bZc=s(["El arroz es rico.","C\u01a1m ngon."],t.s)
B.aW0=s(["Las fresas son rojas y dulces.","D\xe2u t\xe2y \u0111\u1ecf v\xe0 ng\u1ecdt."],t.s)
B.c3m=s(["El pastel de cumplea\xf1os es grande.","B\xe1nh sinh nh\u1eadt to."],t.s)
B.avF=s(["Mam\xe1 hace empanadillas.","M\u1eb9 g\xf3i b\xe1nh bao."],t.s)
B.a85=s(["Los fideos son largos.","S\u1ee3i m\xec d\xe0i."],t.s)
B.bX0=s(["La luna es redonda.","M\u1eb7t tr\u0103ng tr\xf2n."],t.s)
B.NX=s(["Juego con mi amigo.","T\xf4i ch\u01a1i v\u1edbi b\u1ea1n."],t.s)
B.b3m=s(["Hay muchas estrellas en el cielo.","Tr\xean tr\u1eddi c\xf3 nhi\u1ec1u sao."],t.s)
B.xO=s(["Las nubes blancas flotan en el cielo.","M\xe2y tr\u1eafng tr\xf4i tr\xean b\u1ea7u tr\u1eddi."],t.s)
B.aVQ=s(["Quiero a mi mam\xe1.","T\xf4i y\xeau m\u1eb9."],t.s)
B.a4f=s(["\xa1Hola, maestra!","Em ch\xe0o c\xf4 \u1ea1!"],t.s)
B.akp=s(["El mar es azul.","Bi\u1ec3n xanh."],t.s)
B.AV=s(["Hacemos un mu\xf1eco de nieve.","Ch\xfang t\xf4i l\xe0m ng\u01b0\u1eddi tuy\u1ebft."],t.s)
B.bEN=s(["Vamos a jugar al parque.","Ch\xfang t\xf4i \u0111i ch\u01a1i c\xf4ng vi\xean."],t.s)
B.bvU=s(["Hay m\xe9dicos en el hospital.","\u1ede b\u1ec7nh vi\u1ec7n c\xf3 b\xe1c s\u0129."],t.s)
B.b9e=s(["El sal\xf3n de clases est\xe1 limpio.","L\u1edbp h\u1ecdc s\u1ea1ch s\u1ebd."],t.s)
B.aZD=s(["El m\xe9dico me revisa.","B\xe1c s\u0129 kh\xe1m b\u1ec7nh cho t\xf4i."],t.s)
B.c1r=s(["El polic\xeda ayuda a todos.","Ch\xfa c\u1ea3nh s\xe1t gi\xfap \u0111\u1ee1 m\u1ecdi ng\u01b0\u1eddi."],t.s)
B.aop=s(["El cocinero prepara la comida.","\u0110\u1ea7u b\u1ebfp n\u1ea5u c\u01a1m."],t.s)
B.aiO=s(["Vamos de compras al supermercado.","Ch\xfang t\xf4i \u0111i si\xeau th\u1ecb mua \u0111\u1ed3."],t.s)
B.afs=s(["El estudiante escribe.","H\u1ecdc sinh vi\u1ebft ch\u1eef."],t.s)
B.aGk=s(["La maestra escribe en el pizarr\xf3n.","C\xf4 gi\xe1o vi\u1ebft ch\u1eef l\xean b\u1ea3ng."],t.s)
B.Wz=s(["Ten cuidado al cruzar la calle.","H\xe3y c\u1ea9n th\u1eadn khi qua \u0111\u01b0\u1eddng."],t.s)
